s = open('fuzz_expr.py').read()
start = s.index("class Gen:")
end = s.index("rng = random.Random(")
gen = '''class Gen:
    """Type-aware random expression generator."""

    TAGS = {
        'int': ('N', ('n', 'ta'), ('w:n', 'a:n', 'ta:i')),
        'bool': ('B', ('b',), ('w:b', 'a:b', 'ta:b')),
        'char': ('C', ('c',), ()),
        'string': ('S', ('s',), ('w:s', 'a:s')),
        'enum': ('E', (), ()),
        'arrayN': ('V', ('v',), ()),
        'arrayT': ('VA', ('ta',), ()),
        'structW': ('W', ('w', 'a'), ()),
        'structT': ('T', (), ()),
    }

    def __init__(self, rng, decls, types, scope):
        self.rng = rng
        self.decls = decls
        self.types = types
        self.scope = scope
        self.vars_by_tag = {}
        for tag, (_type_name, vars_, _fields) in self.TAGS.items():
            self.vars_by_tag[tag] = [n for n in vars_ if n in scope]
        self.bits = {n: t.bits for n, t in scope.items() if isinstance(t, Int)}

    def const(self, tag, depth=0):
        rng = self.rng
        name = self.TAGS[tag][0]
        if tag == 'int':
            return ['const', name, rng.randint(0, (1 << self.types['N'].bits) - 1)]
        if tag == 'bool':
            return ['const', name, rng.random() < 0.5]
        if tag == 'char':
            return ['const', name, rng.choice(['\\x00', 'A', 'z', '\\xff'])]
        if tag == 'string':
            return ['const', name, ''.join(rng.choice(['a', 'b', 'c', '\\x00', '\\xff'])
                                           for _ in range(self.types['S'].maxsize))]
        if tag == 'enum':
            return ['const', name, rng.choice(['e0', 'e1', 'e2'])]
        if tag == 'arrayN':
            return ['const', name, [rng.randint(0, 15)
                                    for _ in range(self.types['V'].size)]]
        if tag == 'arrayT':
            return ['const', name, [{'n': rng.randint(0, 15), 'b': rng.random() < 0.5}
                                    for _ in range(self.types['VA'].size)]]
        if tag == 'structW':
            return ['const', name, {'n': rng.randint(0, 15), 'b': rng.random() < 0.5,
                                    's': ''.join(rng.choice('ab\\x00') for _ in range(self.types['S'].maxsize)),
                                    'v': [rng.randint(0, 15) for _ in range(self.types['V'].size)]}]
        if tag == 'structT':
            return ['const', name, {'n': rng.randint(0, 15), 'b': rng.random() < 0.5}]
        raise AssertionError(tag)

    def expr(self, tag, depth):
        """A random expression whose underlying type matches ``tag``."""
        rng = self.rng
        vars_ = self.vars_by_tag[tag]
        if depth <= 0:
            if vars_ and rng.random() < 0.7:
                return ['var', rng.choice(vars_)]
            return self.const(tag)
        pick = rng.random()
        if pick < 0.25 and vars_:
            return ['var', rng.choice(vars_)]
        if pick < 0.4:
            return self.const(tag, depth)
        if tag == 'int':
            kind = rng.choice(['add', 'sub', 'index', 'field'])
            if kind in ('add', 'sub'):
                return [kind, self.expr('int', depth - 1), self.expr('int', depth - 1)]
            if kind == 'index':
                return ['index', self.expr('arrayN', depth - 1),
                        rng.randrange(self.types['V'].size)]
            return ['field', self.expr(rng.choice(['structW', 'structT']), depth - 1), 'n']
        if tag == 'bool':
            kind = rng.choice(['not', 'and', 'or', 'implies', 'eq', 'ne', 'lt', 'le',
                               'gt', 'ge', 'all', 'match', 'field'])
            if kind in ('not', 'and', 'or', 'implies'):
                if kind == 'not':
                    return ['not', self.expr('bool', depth - 1)]
                return [kind, self.expr('bool', depth - 1), self.expr('bool', depth - 1)]
            if kind in ('lt', 'le', 'gt', 'ge'):
                return [kind, self.expr('int', depth - 1), self.expr('int', depth - 1)]
            if kind in ('eq', 'ne'):
                inner = rng.choice(['int', 'bool', 'char', 'string', 'enum',
                                    'arrayN', 'arrayT', 'structW', 'structT'])
                return [kind, self.expr(inner, depth - 1), self.expr(inner, depth - 1)]
            if kind == 'all':
                array_tag = rng.choice(['arrayN', 'arrayT'])
                element_tag = 'int' if array_tag == 'arrayN' else 'structT'
                binding = 'z%d' % rng.randint(0, 3)
                inner_scope = dict(self.scope)
                inner_scope[binding] = self.types['N' if element_tag == 'int' else 'T']
                sub = Gen(rng, self.decls, self.types, inner_scope)
                return ['all', binding, self.expr(array_tag, depth - 1),
                        sub.expr('bool', depth - 1)]
            if kind == 'match':
                return ['match', self.expr('string', depth - 1), self.pattern()]
            return ['field', self.expr(rng.choice(['structW', 'structT']), depth - 1), 'b']
        if tag in ('arrayN', 'arrayT'):
            return ['var', rng.choice(vars_)] if vars_ else self.const(tag)
        if tag in ('structW', 'structT'):
            return ['var', rng.choice(vars_)] if vars_ else self.const(tag)
        return ['var', rng.choice(vars_)] if vars_ else self.const(tag)

    def pattern(self):
        rng = self.rng
        pieces = []
        for _ in range(rng.randint(0, 3)):
            alt = []
            for _ in range(rng.randint(0, 3)):
                atom = rng.choice(['a', 'b', 'c', '[a-c]', '(a|b)', 'ab', '[ab]',
                                   '\\\\.', 'x', '[a-cx-z]', '()', 'a*b', '[\\\\]a]',
                                   '[a\\\\-b]', 'ab|', '|ab', '[b-a]'])
                if rng.random() < 0.35:
                    atom = atom + '*'
                alt.append(atom)
            pieces.append(''.join(alt))
        return '|'.join(pieces)

'''
open('fuzz_expr.py','w').write(s[:start] + gen + s[end:])
